import tarfile
import tempfile
import os
import json

def get_build_metadata(build_tarball):
    with tempfile.TemporaryDirectory() as td:
        tar = tarfile.open(build_tarball)
        tar.extractall(path=os.path.join(td, '../'))

        for member in tar.getmembers():
            if member.name == "build-info.json":
                with open(os.path.join(td, member.name)) as f:
                    return json.load(f)

        raise Exception("build-info.json not found in tarball")

